## If you must keep synchronous threads

```csharp
public class EventProcessor
{
    private readonly ManualResetEventSlim _newEvent = new(false);
    private readonly Queue<string> _queue = new();
    private readonly object _lock = new();
    private Thread? _thread;
    private CancellationTokenSource? _cts;

    public void Start()
    {
        _cts = new CancellationTokenSource();
        _thread = new Thread(() => RunLoop(_cts.Token));
        _thread.Start();
    }

    private void RunLoop(CancellationToken token)
    {
        var handles = new[] { _newEvent.WaitHandle, token.WaitHandle };
        while (!token.IsCancellationRequested)
        {
            // Wakes on either new event OR cancellation
            WaitHandle.WaitAny(handles);
            if (token.IsCancellationRequested) break;

            _newEvent.Reset();
            string? item = null;
            lock (_lock)
            {
                if (_queue.Count > 0)
                    item = _queue.Dequeue();
            }
            if (item is not null)
                Handle(item);
        }
    }

    public void Enqueue(string item)
    {
        lock (_lock) { _queue.Enqueue(item); }
        _newEvent.Set();
    }

    public void Stop()
    {
        _cts?.Cancel();                  // wakes WaitAny immediately
        _thread?.Join(TimeSpan.FromSeconds(5));
        _cts?.Dispose();
        _newEvent.Dispose();
    }

    private void Handle(string item) { /* your logic */ }
}
```

